let currentLanguage = (()=>{try{const saved=localStorage.getItem(LANGUAGE_KEY);if(saved==='en'||saved==='vi')return saved;}catch{}return (navigator.language||'').toLowerCase().startsWith('vi')?'vi':'en';})();
let currentTheme=(()=>{try{const saved=localStorage.getItem(THEME_KEY);if(saved==='dark'||saved==='light')return saved;}catch{}return 'dark';})();
let setupState=null,runtimeState=null,permissionState=null,updateState=null,multiNodeState=null,executionPolicyState=null,adminRequests=[],pairingState=null,activePairingCode=null;
let currentNotificationKeys=[];
let notificationReadKeys=(()=>{try{const parsed=JSON.parse(localStorage.getItem(NOTIFICATION_READ_KEY)||'[]');return new Set(Array.isArray(parsed)?parsed.filter(v=>typeof v==='string').slice(-200):[]);}catch{return new Set();}})();
function persistNotificationReadKeys(){try{localStorage.setItem(NOTIFICATION_READ_KEY,JSON.stringify([...notificationReadKeys].slice(-200)));}catch{}}

function applyTheme(theme,persist=true){currentTheme=theme==='light'?'light':'dark';document.documentElement.setAttribute('data-theme',currentTheme);const btn=$('themeToggle');if(btn){btn.textContent=currentTheme==='dark'?'☀':'☾';btn.setAttribute('aria-label',currentTheme==='dark'?'Switch to light theme':'Switch to dark theme');btn.title=btn.getAttribute('aria-label');}if(persist){try{localStorage.setItem(THEME_KEY,currentTheme);}catch{}}}
function showToast(message,type='success'){const host=$('toastContainer');if(!host)return;const el=document.createElement('div');el.className='toast '+type;el.textContent=message;host.appendChild(el);setTimeout(()=>el.remove(),3200);}
function openDialog(id){const dialog=$(id);if(dialog&&!dialog.open)dialog.showModal();}
function closeDialog(id){const dialog=$(id);if(dialog&&dialog.open)dialog.close();}
function installBackdropClose(id){const dialog=$(id);if(!dialog)return;dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close();});}
let fullAccessDecision=null;
function askFullAccess(){return new Promise(resolve=>{fullAccessDecision=resolve;openDialog('fullAccessConfirmModal');});}
function finishFullAccessDecision(value){const resolve=fullAccessDecision;fullAccessDecision=null;closeDialog('fullAccessConfirmModal');if(resolve)resolve(value);}
function t(key,vars={}){let value=(translations[currentLanguage]&&translations[currentLanguage][key])||translations.en[key]||key;for(const [name,replacement] of Object.entries(vars))value=value.replaceAll('{'+name+'}',String(replacement));return value;}
function applyLanguage(lang,persist=true){currentLanguage=lang==='vi'?'vi':'en';document.documentElement.lang=currentLanguage;document.title=t('pageTitle');document.querySelectorAll('[data-i18n]').forEach(el=>{el.textContent=t(el.dataset.i18n);});document.querySelectorAll('[data-i18n-html]').forEach(el=>{el.innerHTML=t(el.dataset.i18nHtml);});document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{el.setAttribute('placeholder',t(el.dataset.i18nPlaceholder));});if($('openSetup')){$('openSetup').title=t('setupAdvancedTitle');$('openSetup').setAttribute('aria-label',t('setupAdvancedTitle'));}if($('closeSetup'))$('closeSetup').setAttribute('aria-label',t('cancel'));if($('closeFullAccessConfirm'))$('closeFullAccessConfirm').setAttribute('aria-label',t('cancel'));$('langEn').classList.toggle('active',currentLanguage==='en');$('langVi').classList.toggle('active',currentLanguage==='vi');$('langEn').setAttribute('aria-pressed',String(currentLanguage==='en'));$('langVi').setAttribute('aria-pressed',String(currentLanguage==='vi'));if(persist){try{localStorage.setItem(LANGUAGE_KEY,currentLanguage);}catch{}}if(setupState)renderStatus(setupState);if(runtimeState)renderRuntime(runtimeState);if(permissionState)renderPermissions(permissionState);if(updateState)renderUpdate(updateState);if(multiNodeState)renderMultiNode(multiNodeState);renderControlNotifications();}
const CSRF_RELOAD_KEY='rwmcp.csrf-reload-at';
async function api(path, options={}){const r=await fetch(path,{...options,headers:{...headers,...(options.headers||{})}});const data=await r.json().catch(()=>({error:t('invalidResponse')}));if(r.status===403&&String(data.error||'').includes('Invalid or missing setup token.')){let shouldReload=true;try{const last=Number(sessionStorage.getItem(CSRF_RELOAD_KEY)||'0');shouldReload=!Number.isFinite(last)||Date.now()-last>10000;if(shouldReload)sessionStorage.setItem(CSRF_RELOAD_KEY,String(Date.now()));}catch{}if(shouldReload){location.reload();return await new Promise(()=>{});}}if(!r.ok)throw new Error(data.error||('HTTP '+r.status));return data;}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function actionLabel(action){const map={Start:'startTunnel',Restart:'restart',Stop:'stop',RegisterStartup:'autostartOn',UnregisterStartup:'autostartOff'};return map[action]?t(map[action]):action;}
function renderReadiness(){if(!setupState||!runtimeState)return;const configured=!!setupState.settings.tunnelId&&setupState.runtimeApiKeyStored&&setupState.tunnelClientInstalled;const ready=configured&&runtimeState.mcpHealthy===true&&runtimeState.tunnelReady===true&&runtimeState.httpAuth==='bearer';const box=$('readiness');if(ready){box.className='ready good';box.innerHTML='<b>'+t('readyTitle')+'</b><br><span class="muted">'+t('readyHelp')+'</span>';}else if(configured){box.className='ready warn';box.innerHTML='<b>'+t('configuredTitle')+'</b><br><span class="muted">'+t('configuredHelp')+'</span>';}else{box.className='ready warn';box.innerHTML='<b>'+t('firstSetupTitle')+'</b><br><span class="muted">'+t('firstSetupHelp')+'</span>';}}
function renderStatus(s){setupState=s;const versionBadge=$('versionBadge');if(versionBadge){versionBadge.textContent='v'+esc(s.version||'-');versionBadge.title='Remote Workstation MCP v'+esc(s.version||'-');}$('port').value=s.settings.mcpPort;$('controlPort').value=s.settings.controlPort||8684;$('workspace').value=s.settings.workspaceRoot;$('tunnel').value=s.settings.tunnelId||'';$('org').value=s.settings.organizationId||'';$('managed').checked=!!s.settings.cloudflaredManaged;const needsSetup=s.onboardingRequired===true||!s.settings.tunnelId||!s.runtimeApiKeyStored;document.body.classList.toggle('onboarding',needsSetup);const firstRun=$('firstRunCard');const access=$('accessCard');if(firstRun)firstRun.hidden=!needsSetup;if(access)access.hidden=needsSetup;if(needsSetup&&$('bootstrapTunnel')&&!$('bootstrapTunnel').value)$('bootstrapTunnel').value=s.settings.tunnelId||'';$('portHelp').innerHTML=s.configuredPortOwnedByManagedRuntime?'<span class="ok">'+t('portManaged',{port:s.settings.mcpPort})+'</span>':s.configuredPortFree?'<span class="ok">'+t('portAvailable',{port:s.settings.mcpPort})+'</span>':'<span class="warntext">'+t('portBusy',{port:s.settings.mcpPort,recommended:s.recommendedMcpPort})+'</span>';$('status').innerHTML='<b>Remote Workstation MCP v'+esc(s.version)+'</b><br>Device: <b>'+esc((s.identity&&s.identity.name)||'-')+'</b> <span class="muted">'+esc((s.identity&&s.identity.id)||'')+'</span><br>ChatGPT app: <span class="ok">'+esc(s.recommendedAppName||'Remote Workstation')+'</span><br>'+t('runtimeKey')+': <span class="'+(s.runtimeApiKeyStored?'ok':'warntext')+'">'+(s.runtimeApiKeyStored?t('storedSecurely'):t('notStored'))+'</span><br>'+t('tunnelClient')+': <span class="'+(s.tunnelClientInstalled?'ok':'warntext')+'">'+(s.tunnelClientInstalled?t('installed'):t('notInstalled'))+'</span><br>'+t('workspace')+': <span class="'+(s.workspaceExists?'ok':'warntext')+'">'+(s.workspaceExists?t('ready'):t('willBeCreated'))+'</span>';renderReadiness();}
function renderRuntime(r){runtimeState=r;if(r.supported===false){$('runtimeMetrics').innerHTML='<div class="metric"><b>Control Center</b><span class="ok">ONLINE</span></div><div class="metric"><b>'+t('runtime')+'</b><span>'+t('windowsOnly')+'</span></div>';return;}const running=r.running===true,mcp=r.mcpHealthy===true,connection=(r.connectionState||((r.tunnelReady===true)?'ONLINE':(running?'RECONNECTING':'OFFLINE'))),connectionClass=connection==='ONLINE'?'ok':connection==='OFFLINE'?'badtext':'warntext',connectionText=connection==='ONLINE'?t('online'):connection==='OFFLINE'?t('offline'):t('reconnecting');$('runtimeMetrics').innerHTML='<div class="metric"><b>Control Center</b><span class="ok">ONLINE</span></div><div class="metric"><b>'+t('supervisor')+'</b><span class="'+(running?'ok':'warntext')+'">'+(running?t('running'):t('stopped'))+'</span></div><div class="metric"><b>MCP</b><span class="'+(mcp?'ok':'warntext')+'">'+(mcp?t('healthy'):t('offline'))+'</span></div><div class="metric"><b>'+t('tunnel')+'</b><span class="'+connectionClass+'">'+connectionText+'</span></div><div class="metric"><b>'+t('auth')+'</b><span>'+esc(r.httpAuth||'-')+'</span></div>';let detail=r.mcpVersion?t('runtimeOnPort',{version:'<b>'+esc(r.mcpVersion)+'</b>',port:'<b>'+esc(r.port)+'</b>'}):'';if(r.connectionReason&&connection!=='ONLINE')detail+=(detail?'<br>':'')+'<span class="muted">'+esc(r.connectionReason)+(r.reconnectAttempt?' - attempt '+esc(r.reconnectAttempt):'')+'</span>';if(r.error)detail+=(detail?'<br>':'')+'<span class="badtext">'+esc(r.error)+'</span>';$('runtimeMessage').innerHTML=detail;renderReadiness();}
