function renderDevices(data){pairingState=data;const host=$('pairHost');if(host){const current=host.value;host.innerHTML=(data.bootstrapHosts||[]).map(h=>'<option value="'+esc(h.id)+'">'+esc(h.name)+' - '+esc(h.hostname)+'</option>').join('');if(current&&[...host.options].some(o=>o.value===current))host.value=current;}const box=$('pairedDevices');if(!box)return;const devices=data.devices||[];if(!devices.length){box.innerHTML='<span class="muted">'+t('noPairedDevices')+'</span>';return;}box.innerHTML=devices.map(d=>'<div class="metric" style="margin-top:8px"><b>'+esc(d.name)+'</b><span>'+esc(d.id)+' | '+esc(d.platform)+' | '+esc(d.hostname)+' · v'+esc(d.version)+'</span><div class="muted">'+esc((d.capabilities||[]).join(', '))+(d.lastSeenAt?' | last seen '+esc(d.lastSeenAt):'')+'</div><button class="danger revoke-device" type="button" data-device-id="'+esc(d.id)+'" style="margin-top:8px">'+t('revokeDevice')+'</button></div>').join('');box.querySelectorAll('.revoke-device').forEach(button=>button.onclick=()=>revokePairedDevice(button.dataset.deviceId));}
